import json, itertools
w=json.loads(context)
qs={s:[q for q in w['quotes'] if q['sku']==s and q['quality']=='approved' and q['units']>=w['skus'][s]['demand'] and q['units']<=w['skus'][s]['demand']+2 and q['arrival']<=w['skus'][s]['deadline']] for s in 'ABCDE'}
vs={v['id']:v for v in w['vendors']}
best=None
for sel in itertools.product(*(qs[s] for s in 'ABCDE')):
 d={q['sku']:q for q in sel}
 if any(q['needs_same_vendor_sku'] and d[q['needs_same_vendor_sku']]['vendor']!=q['vendor'] for q in sel): continue
 vendors={q['vendor'] for q in sel}
 if len(vendors)<3 or sum(q['carbon'] for q in sel)>w['carbon_cap']: continue
 ok=True; cost=0
 for v in vendors:
  vq=[q for q in sel if q['vendor']==v]; units=sum(q['units'] for q in vq); gross=sum(q['units']*q['unit_cents'] for q in vq); rule=vs[v]
  if units>rule['unit_cap']: ok=False; break
  merch=(gross*(10000-rule['tier_bps'])+5000)//10000 if units>=rule['tier_units'] else gross
  cost+=merch
  if gross<rule['free_shipping_gross']: cost+=rule['shipping_cents']
  if len(vq)>=2 and merch>=rule['rebate_merchandise_min']: cost-=rule['rebate_cents']
 if ok and (best is None or cost<best): best=cost
print(FINAL(str(best)))
